public int firstUniqChar(String s) {
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int occurrences = 0;
        for (int j = 0; j < s.length(); j++) {
            if (s.charAt(j) == c) occurrences++;
        }
        if (occurrences == 1) return i;
    }
    return -1;
}

